// Local prototype state: cancellation and logout are not server-side operations.
const signout=document.createElement('button');signout.className='secondary';signout.textContent='Log out';signout.onclick=()=>{if(!confirm('Log out on this device? Your local ride requests and offered rides will stay here.'))return;localStorage.removeItem('cr_profile');profileData={};profileImage='';intro.classList.remove('hidden');onboarding(0);go('discover')};$('profile').querySelector('.extended').appendChild(signout);

function rideDeparture(x){if(!x.date)return null;let time=x.time||'';let parsed;if(/^\d{4}-\d{2}-\d{2}$/.test(x.date)){let hour=0,minute=0,m=time.match(/^(\d{1,2}):(\d{2})(?:\s*(AM|PM))?$/i);if(m){hour=+m[1];minute=+m[2];if(m[3]){hour%=12;if(m[3].toUpperCase()==='PM')hour+=12}}parsed=new Date(x.date+'T'+String(hour).padStart(2,'0')+':'+String(minute).padStart(2,'0')+':00')}else parsed=new Date(x.date+' '+time);return Number.isNaN(parsed.getTime())?null:parsed}
function deadlineInfo(x){let departure=rideDeparture(x);if(!departure||!x.time||x.time==='Time TBD')return {valid:false};let ms=departure.getTime()-24*3600000-Date.now();return {valid:true,open:ms>0,ms,departure}}
function timeLeft(ms){let m=Math.ceil(ms/60000),days=Math.floor(m/1440),hours=Math.floor((m%1440)/60),mins=m%60;return (days?days+'d ':'')+hours+'h '+mins+'m'}
function addDeadline(row,x,removeHandler){let info=deadlineInfo(x),old=[...row.querySelectorAll('button')].find(b=>b.textContent.trim()==='Remove demo request');if(old)old.remove();let area=document.createElement('div');area.className='cancel-area';if(!info.valid){area.innerHTML='<p class="note">Cancellation deadline unavailable: ride departure time is missing.</p>'}else if(!info.open){area.innerHTML='<p class="note">The 24-hour cancellation deadline has passed. Contact support for help.</p>'}else{let text=document.createElement('p');text.className='cancel-timer';text.dataset.deadline=String(info.departure.getTime()-24*3600000);text.textContent='Cancel within '+timeLeft(info.ms)+' (24 hours before departure)';let button=document.createElement('button');button.className='secondary';button.textContent='Cancel ride';button.onclick=()=>{if(Date.now()>=info.departure.getTime()-24*3600000){renderTrips();return}if(confirm('Cancel this demo ride?'))removeHandler()};area.append(text,button)}row.appendChild(area)}
const priorTripRenderer=renderTrips;renderTrips=function(){priorTripRenderer();const list=$('tripList');let rows=[...list.querySelectorAll('.trip-row')];for(const row of rows){let badge=row.querySelector('.tag')?.textContent||'';if(badge.includes('Offered ride')){let route=row.querySelector('b')?.textContent;let r=demo.drivers.find(d=>d.from+' → '+d.to===route);if(r)addDeadline(row,r,()=>{demo.drivers=demo.drivers.filter(d=>d.id!==r.id);let idx=rides.findIndex(d=>d.id===r.id);if(idx>=0)rides.splice(idx,1);saveDemo();render(rides);renderTrips()})}else{let button=[...row.querySelectorAll('button')].find(b=>b.textContent.trim()==='Remove demo request');let onclick=button?.getAttribute('onclick')||'';let match=onclick.match(/cancel\((\d+)\)/);let x=match&&requests.find(t=>t.id===Number(match[1]));if(x)addDeadline(row,x,()=>{requests=requests.filter(t=>t.id!==x.id);localStorage.setItem('cr_requests',JSON.stringify(requests));renderTrips()})}}};
setInterval(()=>{document.querySelectorAll('.cancel-timer').forEach(el=>{let remaining=Number(el.dataset.deadline)-Date.now();if(remaining<=0){if(!$('trips').classList.contains('hidden'))renderTrips()}else el.textContent='Cancel within '+timeLeft(remaining)+' (24 hours before departure)'})},30000);
// Include departure time with new requests so the cutoff can be calculated.
const wrapRequestWithTime=requestRide;requestRide=function(id){wrapRequestWithTime(id);let ride=rides.find(r=>r.id===id),button=$('sendRequest');if(!button)return;button.addEventListener('click',()=>{let x=requests[requests.length-1];if(x&&x.rideId===id&&!x.time){x.time=ride.time;localStorage.setItem('cr_requests',JSON.stringify(requests))}})};
